// Assim Partial e Readonly são feitos por dentro
type MeuPartial<T> = { [K in keyof T]?: T[K] };
type MeuReadonly<T> = { readonly [K in keyof T]: T[K] };

// O sinal de menos remove modificadores: tira readonly e ? de tudo
type Completo<T> = { -readonly [K in keyof T]-?: T[K] };

interface Config {
  readonly porta?: number;
  readonly host?: string;
}
type ConfigCompleta = Completo<Config>; // { porta: number; host: string }

// Remapeando chaves com `as`
type Getters<T> = {
  [K in keyof T as `get${Capitalize<string & K>}`]: () => T[K];
};
type UserGetters = Getters<{ nome: string; idade: number }>;
// { getNome: () => string; getIdade: () => number }

// Filtrando chaves: mapear para `never` remove a chave
type SoStrings<T> = { [K in keyof T as T[K] extends string ? K : never]: T[K] };
type Textos = SoStrings<{ nome: string; idade: number; email: string }>;
// { nome: string; email: string }

// T extends U ? X : Y é um "if" no nível dos tipos
type EhString<T> = T extends string ? 'sim' : 'não';
type A = EhString<'oi'>; // 'sim'
type B = EhString<42>;   // 'não'

// infer captura um pedaço do tipo dentro da condição
type ElementoDe<T> = T extends readonly (infer E)[] ? E : never;
type N = ElementoDe<number[]>; // number

type Desembrulha<T> = T extends Promise<infer U> ? Desembrulha<U> : T;
type Texto = Desembrulha<Promise<Promise<string>>>; // string (como o Awaited nativo)

// É assim que o ReturnType nativo funciona
type Retorno<F> = F extends (...args: never[]) => infer R ? R : never;
type X = Retorno<() => { ok: boolean }>; // { ok: boolean }

// Em uniões, a condição é distributiva: roda para cada membro
type SemNulos<T> = T extends null | undefined ? never : T;
type Y = SemNulos<string | null | undefined>; // string (como o NonNullable)

type Metodo = 'get' | 'post';
type Recurso = 'users' | 'posts';
type Permissao = `${Metodo}:${Recurso}`;
// 'get:users' | 'get:posts' | 'post:users' | 'post:posts'

type Evento = 'click' | 'focus';
type Handler = `on${Capitalize<Evento>}`; // 'onClick' | 'onFocus'

// Extraindo os parâmetros de uma rota com infer recursivo
type Params<Rota extends string> =
  Rota extends `${string}:${infer P}/${infer Resto}`
    ? P | Params<`/${Resto}`>
    : Rota extends `${string}:${infer P}`
      ? P
      : never;

type P1 = Params<'/users/:userId/posts/:postId'>; // 'userId' | 'postId'

function montarUrl<R extends string>(rota: R, params: Record<Params<R>, string>): string {
  return rota.replace(/:(\w+)/g, (_, nome: string) => params[nome as Params<R>]);
}

console.log(montarUrl('/users/:userId/posts/:postId', { userId: '1', postId: '9' }));
// '/users/1/posts/9'

// @ts-expect-error: falta postId
montarUrl('/users/:userId/posts/:postId', { userId: '1' });

// Um array `as const` vira a fonte da verdade, em runtime E no tipo
const PAPEIS = ['admin', 'editor', 'leitor'] as const;
type Papel = (typeof PAPEIS)[number]; // 'admin' | 'editor' | 'leitor'

function isPapel(x: string): x is Papel {
  return (PAPEIS as readonly string[]).includes(x);
}

// Indexed access: navega dentro de um tipo
interface Pedido {
  id: string;
  itens: { sku: string; qtd: number }[];
  cliente: { nome: string; endereco: { cidade: string } };
}
type Item = Pedido['itens'][number];                   // { sku: string; qtd: number }
type Cidade = Pedido['cliente']['endereco']['cidade']; // string

// Mapa "nome → dados" + generic: a base dos jobs tipados do BullMQ (módulo 10)
interface Eventos {
  'user.criado': { id: string; email: string };
  'pedido.pago': { pedidoId: string; valor: number };
}

function publicar<K extends keyof Eventos>(nome: K, dados: Eventos[K]): void {
  console.log(nome, dados);
}

publicar('pedido.pago', { pedidoId: 'p1', valor: 99.9 }); // ✅
// @ts-expect-error: dados de outro evento
publicar('user.criado', { pedidoId: 'p1', valor: 99.9 });

console.log(isPapel('admin'), isPapel('root')); // true false

// Todo ID é string: nada impede passar um PedidoId onde se espera um UserId
declare const marca: unique symbol;
type Brand<T, Nome extends string> = T & { readonly [marca]: Nome };

type UserId = Brand<string, 'UserId'>;
type PedidoId = Brand<string, 'PedidoId'>;

// O jeito "oficial" de criar um UserId passa pela validação
function toUserId(raw: string): UserId {
  if (!/^u_[a-z0-9]+$/.test(raw)) throw new Error(`UserId inválido: ${raw}`);
  return raw as UserId;
}

function buscarUsuario(id: UserId): string {
  return `buscando ${id}`;
}

const userId = toUserId('u_123');
const pedidoId = 'p_999' as PedidoId;

buscarUsuario(userId);   // ✅
// @ts-expect-error: PedidoId não é UserId
buscarUsuario(pedidoId);
// @ts-expect-error: string crua também não serve
buscarUsuario('u_123');

// Em runtime é só uma string: a marca existe apenas para o compilador
console.log(userId.toUpperCase()); // 'U_123'
